import { useCallback, useEffect, useMemo, useState } from 'react';
import { Alert, Anchor, Badge, Button, Card, Group, Loader, Menu, Paper, SimpleGrid, Stack, Text, TextInput, ThemeIcon, Title, Tooltip, UnstyledButton } from '@mantine/core';
import { IconChevronDown, IconExternalLink, IconInfoCircle, IconLink, IconRefresh, IconSearch, IconTopologyStar3 } from '@tabler/icons-react';
import { notifications } from '@mantine/notifications';

import { ApiEndpoints, checkPluginVersion, type InvenTreePluginContext } from '@inventreedb/ui';
import SupplierImportWizard from './SupplierImportWizard';

// A sync is one long server-side request: InvenTree fetches the BOM from
// OMG, matches/updates every BOM line, then reports back to OMG's
// webhook. That regularly takes longer than the 5s default timeout on
// InvenTree's API client ("timeout of 5000ms exceeded"), so the panel
// reported a failure even when the sync finished fine. Only the
// import/sync calls get the longer timeout; everything else keeps the default.
const SYNC_TIMEOUT_MS = 120000;

// Harness imports run on InvenTree's BACKGROUND WORKER now (see the
// plugin's harness_import_job.py): the import endpoint queues a job and
// returns at once, and this polls the job until it finishes. A big
// harness used to run past the web server's request timeout and fail
// with a 500 even though nothing was wrong with it.
const IMPORT_POLL_MS = 2000;
const IMPORT_MAX_WAIT_MS = 15 * 60 * 1000;

async function runHarnessImport(
    api: InvenTreePluginContext['api'],
    body: Record<string, unknown>,
    onProgress?: (message: string) => void,
): Promise<any> {
    const started = await api.post('/plugin/omg-harness-import/import-harness/', body);
    let job = started.data;
    const deadline = Date.now() + IMPORT_MAX_WAIT_MS;
    while (job.status === 'queued' || job.status === 'running') {
        onProgress?.(job.progress || (job.status === 'queued' ? 'Waiting for the background worker…' : 'Working…'));
        if (Date.now() > deadline) {
            throw new Error('The import is still running after 15 minutes. Check back shortly, or look at InvenTree\'s background tasks.');
        }
        await new Promise((resolve) => setTimeout(resolve, IMPORT_POLL_MS));
        const polled = await api.get(`/plugin/omg-harness-import/import-harness/jobs/${job.job_id}/`);
        job = polled.data;
    }
    if (job.status === 'failed') {
        throw new Error(job.error || 'The import failed.');
    }
    return job.batch;
}

interface BatchSummary {
    id: number;
    created_at: string;
    total_items: number;
    matched_items: number;
    flagged_items: number;
    items: any[];
}

interface Candidate {
    pk: number;
    ipn: string;
    name: string;
}

interface PendingPartInfo {
    id: number;
    mpn: string;
    kind: string;
    manufacturer: string;
    description: string;
    url: string;
    spn: string;
    resolved_inventree_pk: number | null;
}

// Live details from OMG (POST /api/inventree/review-context/), attached
// by the plugin's queue endpoint - null when the item doesn't trace back
// to an OMG object, or OMG couldn't be reached.
interface OmgContext {
    label: string;
    wire_no?: number | string | null;
    part_no: string;
    description: string;
    linked_inventree_pk: number | null;
    pending_part: PendingPartInfo | null;
}

interface UnresolvedItem {
    id: number;
    part_number: string;
    reason: string;
    notes: string;
    candidates: Candidate[];
    omg_object_type: string | null;
    omg_object_id: number | null;
    omg_context?: OmgContext | null;
}

interface InvenTreePartRow {
    pk: number;
    name: string;
    IPN: string;
    description: string;
}

// Review list sections, in display order. Items not tied to an OMG object
// (e.g. a stale BOM line, or a harness rename InvenTree refused) go last.
const REVIEW_GROUPS: { key: string; title: string }[] = [
    { key: 'connector', title: 'Connectors' },
    { key: 'wire', title: 'Wires' },
    { key: 'multicore', title: 'Multicore cables' },
    { key: 'accessory', title: 'Accessories' },
    { key: 'junction', title: 'Junctions' },
    { key: 'sub_harness', title: 'Sub-harnesses' },
    { key: 'other', title: 'Other' },
];

// "J2" before "J10", "Wire 9" before "Wire 17".
const naturalCompare = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' }).compare;

function reviewTitle(item: UnresolvedItem): string {
    return item.omg_context?.label || item.part_number;
}

// Wires sort by their actual WireNo from OMG (numeric-aware, so "12A"
// sits after "12"); everything else - and a wire OMG didn't return a
// number for - sorts by its title.
function reviewSortKey(item: UnresolvedItem): string {
    const wireNo = item.omg_context?.wire_no;
    if (item.omg_object_type === 'wire' && wireNo !== null && wireNo !== undefined && wireNo !== '') {
        return String(wireNo);
    }
    return reviewTitle(item);
}

// A problem with a part that's already linked (its related parts, Cavity Map,
// lock choice...) is fixed on that part's OMG panel - not by importing or
// creating another part. Which panel, from what the problem is about.
function fixPanel(notes: string): { panel: string; label: string } {
    const text = notes.toLowerCase();
    if (/(choose one of|needs a |accessor|doesn't fit|does not fit|lock|boot|backshell|cover)/.test(text)) {
        return { panel: 'omg-part-setup?tab=accessories', label: 'Choose it on the part (Accessories)' };
    }
    if (/(related part|contact|blank|seal|cavity|series|gold)/.test(text)) {
        return { panel: 'omg-part-setup?tab=cavities', label: 'Fix its cavities / related parts' };
    }
    return { panel: 'omg-part-setup', label: 'Open its OMG Setup' };
}

const PLUGIN_SLUG = 'omg-harness-import';
const SUPPLIER_SLUG = 'mouser';

/**
 * One item in the "Needs review" list. Besides the existing candidate
 * picks and Dismiss, it can:
 *   - Search InvenTree and link an existing part.
 *   - Import from Mouser in the Import Supplier Part wizard
 *     (SupplierImportWizard - a copy of InvenTree's own wizard, which
 *     plugins can't open directly), with Mouser selected and the pending
 *     MPN / OMG part number already searched. The new part is linked and
 *     reported to OMG when the wizard is closed.
 *   - Create a part by hand with InvenTree's own "Add Part" form (for
 *     parts that aren't on Mouser), pre-filled from OMG's part number,
 *     description and - if there's a pending part - its Mouser link.
 * Resolving reports back to OMG. For a pending part, OMG first checks it's
 * still the same pending part (exists, still used, not resolved elsewhere,
 * same MPN) and refuses otherwise - the item then stays in the queue.
 */
function ReviewItem({ item, context, onChanged }: {
    item: UnresolvedItem;
    context: InvenTreePluginContext;
    onChanged: () => Promise<void>;
}) {
    const omg = item.omg_context || null;
    const pending = omg?.pending_part || null;
    const defaultTerm = pending?.mpn || omg?.part_no || '';

    const [mode, setMode] = useState<'none' | 'search'>('none');
    // linked part with a set-up problem: fix it on the part; replacing the part is tucked away
    const linkedPk = omg?.linked_inventree_pk || null;
    const setupProblem = !!linkedPk && !pending;
    const [showReplace, setShowReplace] = useState(false);
    const fix = fixPanel(item.notes || '');
    const openPart = (panel: string) => context.navigate(`/part/${linkedPk}/${panel}`);
    const [busy, setBusy] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [createdPartPk, setCreatedPartPk] = useState<number | null>(null);

    // Search InvenTree
    const [term, setTerm] = useState(defaultTerm);
    const [partResults, setPartResults] = useState<InvenTreePartRow[] | null>(null);

    // Import Supplier Part wizard. importedPartPk is held until the wizard
    // closes: linking reloads the queue (removing this item), which must not
    // happen while the user is still on the Parameters / Stock steps.
    const [wizardOpen, setWizardOpen] = useState(false);
    const [importedPartPk, setImportedPartPk] = useState<number | null>(null);

    const resolve = useCallback(async (action: 'link' | 'created' | 'dismiss', partPk?: number) => {
        setBusy(true);
        setError(null);
        try {
            await context.api.post(`/plugin/${PLUGIN_SLUG}/unresolved/${item.id}/resolve/`, {
                action,
                part_pk: partPk,
                ...(pending && action !== 'dismiss' ? { pending_part_id: pending.id, pending_mpn: pending.mpn } : {}),
            }, { timeout: SYNC_TIMEOUT_MS });
            notifications.show({
                title: action === 'dismiss' ? 'Dismissed' : 'Linked',
                message: action === 'dismiss' ? 'Item dismissed.' : 'Linked in InvenTree and reported to OMG.',
                color: 'green',
            });
            await onChanged();
        } catch (err: any) {
            const detail = err?.response?.data?.detail || err.message;
            setError(detail);
        } finally {
            setBusy(false);
        }
    }, [context.api, item.id, pending, onChanged]);

    const searchInvenTree = useCallback(async () => {
        if (!term.trim()) return;
        setBusy(true);
        setError(null);
        try {
            const response = await context.api.get('/api/part/', { params: { search: term.trim(), limit: 10 } });
            setPartResults(response.data?.results ?? response.data ?? []);
        } catch (err: any) {
            setError(err?.response?.data?.detail || err.message);
        } finally {
            setBusy(false);
        }
    }, [context.api, term]);



    // InvenTree's own "Add Part" form (the same one as Parts -> Add Part):
    // field definitions, validation and the category picker all come from
    // InvenTree itself. Pre-filled from OMG; on save, the new part is
    // linked and reported back exactly like a Mouser import.
    const createPartForm = context.forms.create({
        url: ApiEndpoints.part_list,
        title: 'Create part in InvenTree',
        fields: {
            category: {},
            name: {},
            IPN: {},
            description: {},
            keywords: {},
            link: {},
            units: {},
            component: {},
            purchaseable: {},
            active: {},
        },
        initialData: {
            // The part number typed in OMG (ConnectorPartNo, ConductorPartNo,
            // accessory/junction PartNo), else the pending Mouser MPN. Never
            // the review item's title - that's a label like "J1", not a part number.
            name: omg?.part_no || pending?.mpn || '',
            description: omg?.description || pending?.description || '',
            link: pending?.url || '',
            component: true,
            purchaseable: true,
            active: true,
        },
        follow: false,
        successMessage: null,
        onFormSuccess: (data: any) => {
            if (data?.pk) {
                setCreatedPartPk(data.pk);
                resolve('created', data.pk);
            }
        },
    });

    const replaceActions = item.omg_object_type && (!setupProblem || showReplace);
    return (
        <Card withBorder radius="md" padding="sm" style={{ borderLeft: `4px solid var(--mantine-color-${pending ? 'blue' : 'yellow'}-5)` }}>
            <Stack gap={6}>
                <Group justify="space-between" align="flex-start" wrap="nowrap">
                    <Stack gap={2} style={{ minWidth: 0 }}>
                        <Group gap="xs">
                            <Text fw={600} size="sm">{reviewTitle(item)}</Text>
                            {omg?.part_no && <Text size="xs" c="dimmed">{omg.part_no}{omg.description ? ` · ${omg.description}` : ''}</Text>}
                        </Group>
                        <Text size="sm">{item.notes}</Text>
                        {pending && (
                            <Group gap="xs">
                                <Badge size="sm" color="blue" variant="light">Picked from Mouser in OMG</Badge>
                                <Text size="xs"><b>{pending.mpn}</b>{pending.manufacturer ? ` (${pending.manufacturer})` : ''}</Text>
                                {pending.url && <Anchor size="xs" href={pending.url} target="_blank">View on Mouser</Anchor>}
                            </Group>
                        )}
                    </Stack>
                    <Group gap="xs" wrap="nowrap">
                        {setupProblem && (
                            <Button size="xs" onClick={() => openPart(fix.panel)}>{fix.label}</Button>
                        )}
                        {item.candidates.slice(0, 2).map((c) => (
                            <Button key={c.pk} size="xs" variant="light" loading={busy} onClick={() => resolve('link', c.pk)}>
                                Use {c.name || c.ipn}
                            </Button>
                        ))}
                        {replaceActions && !item.candidates.length && (
                            <Button size="xs" variant="light" onClick={() => setWizardOpen(true)}>
                                Import from Mouser
                            </Button>
                        )}
                        <Menu position="bottom-end" withinPortal>
                            <Menu.Target>
                                <Button size="xs" variant="default" rightSection={<IconChevronDown size={14} />}>More</Button>
                            </Menu.Target>
                            <Menu.Dropdown>
                                {item.candidates.slice(2).map((c) => (
                                    <Menu.Item key={c.pk} onClick={() => resolve('link', c.pk)}>Use {c.name || c.ipn}</Menu.Item>
                                ))}
                                {setupProblem && fix.panel !== 'omg-part-setup' && (
                                    <Menu.Item onClick={() => openPart('omg-part-setup')}>Open its OMG Setup</Menu.Item>
                                )}
                                {setupProblem && (
                                    <Menu.Item onClick={() => setShowReplace(!showReplace)}>
                                        {showReplace ? 'Keep this part' : 'Use a different part...'}</Menu.Item>
                                )}
                                {replaceActions && (
                                    <>
                                        {item.candidates.length > 0 && <Menu.Item onClick={() => setWizardOpen(true)}>Import from Mouser</Menu.Item>}
                                        <Menu.Item onClick={() => setMode(mode === 'search' ? 'none' : 'search')}>Search InvenTree</Menu.Item>
                                        <Menu.Item onClick={() => createPartForm.open()}>Create part by hand</Menu.Item>
                                    </>
                                )}
                                <Menu.Divider />
                                <Menu.Item color="gray" onClick={() => resolve('dismiss')}>Dismiss</Menu.Item>
                            </Menu.Dropdown>
                        </Menu>
                    </Group>
                </Group>

                {mode === 'search' && (
                    <Stack gap={6}>
                        <Group gap="xs" align="flex-end">
                            <TextInput size="xs" placeholder="Search InvenTree parts" value={term} leftSection={<IconSearch size={14} />}
                                onChange={(e) => setTerm(e.currentTarget.value)}
                                onKeyDown={(e) => e.key === 'Enter' && searchInvenTree()} style={{ flex: 1 }} />
                            <Button size="xs" onClick={searchInvenTree} loading={busy}>Search</Button>
                        </Group>
                        {partResults !== null && partResults.length === 0 && (
                            <Text size="xs" c="dimmed">No InvenTree parts match "{term}".</Text>
                        )}
                        {(partResults || []).map((p) => (
                            <Group key={p.pk} justify="space-between" wrap="nowrap">
                                <Text size="xs"><b>{p.name}</b>{p.IPN ? ` [${p.IPN}]` : ''} - {p.description}</Text>
                                <Button size="xs" variant="light" loading={busy} onClick={() => resolve('link', p.pk)}>Use this part</Button>
                            </Group>
                        ))}
                    </Stack>
                )}

                {createPartForm.modal}
                <SupplierImportWizard
                    context={context}
                    opened={wizardOpen}
                    title={`Import Supplier Part - ${reviewTitle(item)}`}
                    preferredSupplier={SUPPLIER_SLUG}
                    initialTerm={pending ? (pending.spn || pending.mpn) : (omg?.part_no || '')}
                    onImported={(result) => setImportedPartPk(result.part_id)}
                    onClose={() => {
                        setWizardOpen(false);
                        if (importedPartPk) {
                            const pk = importedPartPk;
                            setImportedPartPk(null);
                            setCreatedPartPk(pk);
                            resolve('created', pk);
                        }
                    }}
                />

                {error && (
                    <Alert color="red" p="xs">
                        <Text size="xs">{error}</Text>
                        {createdPartPk && (
                            <Group gap="xs" mt={4}>
                                <Text size="xs">The part was created in InvenTree (#{createdPartPk}) but isn't linked yet.</Text>
                                <Button size="xs" variant="subtle" onClick={() => context.navigate(`/part/${createdPartPk}/`)}>Open part</Button>
                                <Button size="xs" variant="subtle" onClick={() => resolve('created', createdPartPk)}>Try linking again</Button>
                            </Group>
                        )}
                    </Alert>
                )}
            </Stack>
        </Card>
    );
}

// A number with a label - the last sync at a glance
function Stat({ label, value, color, onClick }: { label: string; value: number; color: string; onClick?: () => void }) {
    const body = (
        <Paper withBorder radius="md" p="sm">
            <Text size="xs" c="dimmed" tt="uppercase" fw={700}>{label}</Text>
            <Text size="xl" fw={700} c={color}>{value}</Text>
        </Paper>
    );
    return onClick ? <UnstyledButton onClick={onClick}>{body}</UnstyledButton> : body;
}

interface HarnessSearchResult {
    id: number;
    part_number: string;
    description: string;
}

/**
 * "OMG Harness" — shown on every assembly part's own detail page (see
 * core.py's get_ui_panels). Two states, one panel:
 *   - not yet linked to OMG: search OMG's harness part numbers and
 *     link this exact part to one (target_part_pk pins it, regardless
 *     of whether this part's own name happens to match).
 *   - already linked: the original sync/re-import flow, plus the
 *     inline review queue for flagged items.
 * is_linked itself is checked server-side (LatestBatchForPartView),
 * not inferred from batch history alone — a part can be marked linked
 * manually before ever running a first sync.
 *
 * Backed by:
 *   GET  /plugin/omg-harness-import/batches/latest/?part_pk=...     (is_linked + status, on load)
 *   GET  /plugin/omg-harness-import/harness-search/                 (search, when not yet linked)
 *   POST /plugin/omg-harness-import/import-harness/                 (link-and-import, or re-sync)
 *   GET  /plugin/omg-harness-import/unresolved/?part_pk=...          (review queue)
 *   POST /plugin/omg-harness-import/unresolved/<id>/resolve/         (link/dismiss)
 *   GET  /plugin/omg-harness-import/work-on-url/?part_pk=...         (deep link to OMG)
 */
function OMGHarnessSyncPanel({ context }: { context: InvenTreePluginContext }) {
    const [lastBatch, setLastBatch] = useState<BatchSummary | null>(null);
    const [isLinked, setIsLinked] = useState(false);
    const [loadingStatus, setLoadingStatus] = useState(true);
    const [syncing, setSyncing] = useState(false);
    const [syncProgress, setSyncProgress] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [queue, setQueue] = useState<UnresolvedItem[]>([]);
    const [queueContextError, setQueueContextError] = useState<string | null>(null);

    const groupedQueue = useMemo(() => {
        const known = new Set(REVIEW_GROUPS.map((g) => g.key));
        return REVIEW_GROUPS
            .map((group) => ({
                ...group,
                items: queue
                    .filter((item) => (known.has(item.omg_object_type || '') ? item.omg_object_type : 'other') === group.key)
                    .sort((a, b) => naturalCompare(reviewSortKey(a), reviewSortKey(b))),
            }))
            .filter((group) => group.items.length > 0);
    }, [queue]);

    // Link flow (only used while !isLinked)
    // Pre-filled with the part's own name — that's the overwhelmingly
    // likely search term (OMG matches harnesses by name, same as
    // runSync below), so someone linking this part shouldn't have to
    // retype what's already right there on the page. Still fully
    // editable if the actual OMG harness is named differently.
    const [query, setQuery] = useState(() => context?.instance?.name || '');
    const [searching, setSearching] = useState(false);
    const [searchError, setSearchError] = useState<string | null>(null);
    const [results, setResults] = useState<HarnessSearchResult[]>([]);
    const [linkingPartNumber, setLinkingPartNumber] = useState<string | null>(null);
    // Same reasoning as ImportHarnessPanel.tsx's dashboard widget —
    // distinguishes "haven't searched yet" from "searched, zero
    // matches", so a genuinely empty result gives a clear answer
    // instead of silently showing nothing at all.
    const [hasSearched, setHasSearched] = useState(false);

    const partId = context.id;

    const loadStatus = useCallback(async () => {
        if (!partId) return;
        setLoadingStatus(true);
        try {
            const response = await context.api.get('/plugin/omg-harness-import/batches/latest/', {
                params: { part_pk: partId },
            });
            setIsLinked(!!response.data?.is_linked);
            setLastBatch(response.data?.batch ?? null);
        } catch (err: any) {
            // A failed status check shouldn't block the rest of the panel
            // from being usable — just show the "not linked" state.
            setIsLinked(false);
            setLastBatch(null);
        } finally {
            setLoadingStatus(false);
        }
    }, [partId, context.api]);


    const loadQueue = useCallback(async () => {
        if (!partId) return;
        try {
            const response = await context.api.get('/plugin/omg-harness-import/unresolved/', {
                params: { part_pk: partId },
            });
            // {items, omg_context_error} when scoped to a part (plain list from older plugin versions)
            const data = response.data;
            setQueue(Array.isArray(data) ? data : (data?.items || []));
            setQueueContextError(Array.isArray(data) ? null : (data?.omg_context_error || null));
        } catch (err: any) {
            // Same principle as loadStatus — a failed queue fetch shouldn't
            // break the rest of the panel, just show nothing to review.
            setQueue([]);
        }
    }, [partId, context.api]);

    useEffect(() => {
        loadStatus();
        loadQueue();
    }, [loadStatus, loadQueue]);

    const runSync = useCallback(async () => {
        const partName = context?.instance?.name;
        if (!partName) {
            setError('This part has no name set — OMG matches harnesses by name, so one is needed before syncing.');
            return;
        }
        setSyncing(true);
        setError(null);

        try {
            const batch = await runHarnessImport(context.api, {
                harness_part_number: partName,
                target_part_pk: partId,
            }, setSyncProgress);
            setLastBatch(batch);
            const flagged = batch?.flagged_items || 0;
            notifications.show({
                title: 'Sync complete',
                message: flagged > 0
                    ? `Synced — ${flagged} item(s) need review below.`
                    : 'Synced — everything matched cleanly.',
                color: flagged > 0 ? 'yellow' : 'green',
            });
            if (batch?.reconciliation_pushed === false) {
                notifications.show({
                    title: 'Report-back to OMG failed',
                    message: 'The sync itself succeeded, but InvenTree could not report the result back to OMG. Check the InvenTree Webhook Token setting.',
                    color: 'orange',
                });
            }
            await loadQueue();
        } catch (err: any) {
            const detail = err?.response?.data?.detail || err.message;
            setError(`Sync failed: ${detail}`);
        } finally {
            setSyncing(false);
            setSyncProgress(null);
        }
    }, [context.instance, context.api, partId, loadQueue]);

    // Link flow — search OMG's harness part numbers, then link+import
    // this exact part (target_part_pk) to whichever one is picked.
    // Reuses the same search/import endpoints the dashboard's "Import
    // harness from OMG" widget uses — the only difference is
    // target_part_pk pinning the result to THIS part rather than
    // finding/creating one by name.
    const runSearch = useCallback(async () => {
        if (query.trim().length < 2) {
            setSearchError('Type at least 2 characters');
            setResults([]);
            return;
        }
        setSearching(true);
        setSearchError(null);
        setHasSearched(true);
        try {
            const response = await context.api.get('/plugin/omg-harness-import/harness-search/', {
                params: { q: query.trim() },
            });
            if (response.data.error) {
                setSearchError(response.data.error);
                setResults([]);
            } else {
                setResults(response.data.results || []);
            }
        } catch (err: any) {
            setSearchError(err?.response?.data?.detail || err.message);
            setResults([]);
        } finally {
            setSearching(false);
        }
    }, [query, context.api]);

    const linkHarness = useCallback(async (partNumber: string) => {
        setLinkingPartNumber(partNumber);
        setError(null);
        try {
            const batch = await runHarnessImport(context.api, {
                harness_part_number: partNumber,
                target_part_pk: partId,
            }, setSyncProgress);
            setLastBatch(batch);
            setIsLinked(true);
            notifications.show({
                title: 'Linked',
                message: `Linked to ${partNumber} and imported its BOM.`,
                color: 'green',
            });
            if (batch?.reconciliation_pushed === false) {
                notifications.show({
                    title: 'Report-back to OMG failed',
                    message: 'The link/import itself succeeded, but InvenTree could not report the result back to OMG. Check the InvenTree Webhook Token setting.',
                    color: 'orange',
                });
            }
            await loadQueue();
        } catch (err: any) {
            const detail = err?.response?.data?.detail || err.message;
            setError(`Could not link ${partNumber}: ${detail}`);
        } finally {
            setLinkingPartNumber(null);
            setSyncProgress(null);
        }
    }, [context.api, partId, loadQueue]);

    const workOnInOmg = useCallback(async () => {
        if (!partId) return;
        setError(null);
        try {
            const response = await context.api.get('/plugin/omg-harness-import/work-on-url/', {
                params: { part_pk: partId },
            });
            // Opens in a new tab. Whether that tab is already logged into
            // OMG or not is handled entirely by OMG's own login_required +
            // next= redirect on the far end — nothing to detect here.
            window.open(response.data.url, '_blank');
        } catch (err: any) {
            const detail = err?.response?.data?.detail || err.message;
            setError(`Could not open OMG: ${detail}`);
        }
    }, [partId, context.api]);


    if (loadingStatus) {
        return <Group gap="xs"><Loader size="xs" /><Text size="sm" c="dimmed">Checking the link to OMG…</Text></Group>;
    }

    const header = (title: string, sub: React.ReactNode, actions?: React.ReactNode) => (
        <Group justify="space-between" align="flex-start" wrap="nowrap">
            <Group gap="md" wrap="nowrap">
                <ThemeIcon size={50} radius="md" variant="light" color={isLinked ? 'indigo' : 'gray'}>
                    {isLinked ? <IconTopologyStar3 size={28} /> : <IconLink size={28} />}</ThemeIcon>
                <Stack gap={2}>
                    <Title order={4}>{title}</Title>
                    {sub}
                </Stack>
            </Group>
            {actions}
        </Group>
    );

    if (!isLinked) {
        return (
            <Stack gap="md">
                {header('Link to OMG', <Text size="sm" c="dimmed">Pick the OMG harness this part is - its BOM is imported straight away.</Text>)}
                <Group gap="xs">
                    <TextInput placeholder="OMG harness part number, e.g. R1300G" value={query} leftSection={<IconSearch size={16} />}
                        onChange={(e) => setQuery(e.currentTarget.value)} onKeyDown={(e) => e.key === 'Enter' && runSearch()}
                        style={{ flex: 1 }} />
                    <Button onClick={runSearch} loading={searching}>Search OMG</Button>
                </Group>
                {searchError && <Alert color="orange">{searchError}</Alert>}
                {linkingPartNumber && syncProgress && (
                    <Group gap="xs"><Loader size="xs" /><Text size="sm" c="dimmed">{syncProgress}</Text></Group>
                )}
                {error && <Alert color="red" title="Couldn't link">{error}</Alert>}
                {hasSearched && !searching && !searchError && results.length === 0 && (
                    <Text size="sm" c="dimmed">No harness in OMG matches "{query}".</Text>
                )}
                {results.length > 0 && (
                    <Stack gap={6}>
                        {results.map((r) => (
                            <Card key={r.id} withBorder radius="md" padding="sm">
                                <Group justify="space-between" wrap="nowrap">
                                    <div>
                                        <Text fw={600} size="sm">{r.part_number}</Text>
                                        <Text size="xs" c="dimmed">{r.description}</Text>
                                    </div>
                                    <Button size="xs" loading={linkingPartNumber === r.part_number}
                                        disabled={!!linkingPartNumber && linkingPartNumber !== r.part_number}
                                        onClick={() => linkHarness(r.part_number)}>Link &amp; import</Button>
                                </Group>
                            </Card>
                        ))}
                    </Stack>
                )}
            </Stack>
        );
    }

    const flagged = queue.length;
    return (
        <Stack gap="md">
            {header('OMG Harness',
                <Group gap={6}>
                    <Text size="sm" c="dimmed">{lastBatch ? `Last synced ${new Date(lastBatch.created_at).toLocaleString()}` : 'Not synced with OMG yet'}</Text>
                    <Tooltip multiline w={300} withArrow label="Sync pulls this harness's design from OMG and updates its BOM here - connectors, wires, multicores, accessories. Safe to run any time: quantities update and nothing is removed without being listed for review.">
                        <IconInfoCircle size={14} style={{ color: 'var(--mantine-color-gray-5)' }} />
                    </Tooltip>
                </Group>,
                <Group gap="xs" wrap="nowrap">
                    <Button leftSection={<IconRefresh size={16} />} onClick={runSync} loading={syncing}>{lastBatch ? 'Sync now' : 'Import from OMG'}</Button>
                    <Button variant="light" rightSection={<IconExternalLink size={14} />} onClick={workOnInOmg}>Open in OMG</Button>
                </Group>)}

            {syncing && (
                <Paper withBorder radius="md" p="sm" bg="var(--mantine-color-indigo-0)">
                    <Group gap="xs"><Loader size="xs" /><Text size="sm">{syncProgress || 'Syncing…'}</Text></Group>
                </Paper>
            )}
            {error && <Alert color="red" title="Sync problem">{error}</Alert>}

            {lastBatch && (
                <SimpleGrid cols={3} spacing="sm">
                    <Stat label="BOM lines" value={lastBatch.total_items} color="dark" />
                    <Stat label="Matched" value={lastBatch.matched_items} color="green.7" />
                    <Stat label="Needs review" value={flagged} color={flagged ? 'orange.7' : 'gray.6'}
                        onClick={flagged ? () => document.getElementById('omg-review')?.scrollIntoView({ behavior: 'smooth' }) : undefined} />
                </SimpleGrid>
            )}
            {lastBatch && !flagged && (
                <Group gap={6}><Badge color="green" variant="light">Everything matched</Badge>
                    <Text size="xs" c="dimmed">Nothing to review.</Text></Group>
            )}

            {flagged > 0 && (
                <Stack gap="sm" id="omg-review">
                    <Title order={5}>Needs review</Title>
                    {queueContextError && <Alert color="orange">{queueContextError}</Alert>}
                    {groupedQueue.map((group) => (
                        <Stack key={group.key} gap="xs">
                            <Group gap="xs">
                                <Text size="xs" fw={700} c="dimmed" tt="uppercase">{group.title}</Text>
                                <Badge size="sm" variant="light" color="yellow">{group.items.length}</Badge>
                            </Group>
                            {group.items.map((item) => (
                                <ReviewItem key={item.id} item={item} context={context}
                                    onChanged={async () => { await loadQueue(); await loadStatus(); }} />
                            ))}
                        </Stack>
                    ))}
                </Stack>
            )}
        </Stack>
    );
}

export function RenderOMGHarnessSyncPanel(context: InvenTreePluginContext) {
    checkPluginVersion(context);
    return (
        <OMGHarnessSyncPanel context={context} />
    );
}
